/* Deterministic bare-metal control program for the repository demonstration.
 * The checked-in boot.hex is generated by scripts/build_firmware.py; this file
 * documents the same sequence in conventional RISC-V assembly.
 */
  .section .text
  .globl _start
_start:
  lui  x1, 0x20001             /* DMA register base */
  lui  x2, 0x10000             /* SRAM base */
  lui  x9, 0x20003             /* interrupt controller base */
  addi x10, x0, 31
  sw   x10, 4(x9)              /* enable all five interrupt sources */
  sw   x2, 4(x1)               /* DMA destination */
  addi x3, x0, 8
  sw   x3, 8(x1)               /* eight sensor samples */
  addi x3, x0, 9               /* start + interrupt enable */
  sw   x3, 0(x1)
dma_poll:
  lw   x4, 0(x1)               /* STATUS.DONE is bit 1 */
  andi x4, x4, 2
  beq  x4, x0, dma_poll

  lui  x5, 0x20002             /* accelerator base */
  sw   x2, 4(x5)
  addi x3, x0, 8
  sw   x3, 8(x5)
  addi x3, x0, 9
  sw   x3, 0(x5)
acc_poll:
  lw   x4, 0(x5)
  andi x4, x4, 2
  beq  x4, x0, acc_poll
  lw   x6, 16(x5)              /* expected result: -10 */

  lui  x7, 0x20004             /* UART base */
  addi x8, x0, 'P'
  sw   x8, 0(x7)
  addi x8, x0, 'A'
  sw   x8, 0(x7)
  addi x8, x0, 'S'
  sw   x8, 0(x7)
  sw   x8, 0(x7)
  addi x8, x0, 10
  sw   x8, 0(x7)
  ebreak
